(6520951, 969752, 131284, '<td valign="top">Great blur in this, one of the images that''s really stood out to going through them me so far.</td>', 'Great blur in this, one of the images that''s really stood out to going through them me so far.', '2011-08-30 14:26:34.000000', NULL, 1),
(6520954, 969448, 131284, '<td valign="top">I really like this image though it''s a shame it''s a bit soft (I guess an equipment limitation). Toyed between 6 and 7, though gave you a 7 in the end regardless.</td>', 'I really like this image though it''s a shame it''s a bit soft (I guess an equipment limitation). Toyed between 6 and 7, though gave you a 7 in the end regardless.', '2011-08-30 14:30:15.000000', NULL, 1),
